-- Parent/student access. Staff retain their existing academic privileges.
create table if not exists public.portal_permission_rules (
 id bigint generated by default as identity primary key,
 institution_id bigint not null references public.institutions(id) on delete cascade,
 scope text not null check(scope in ('institution','role','user')),
 role_code text check(role_code in ('student','parent')),
 user_id bigint references public.users(id) on delete cascade,
 permission text not null check(permission in ('grades.view','payments.view','attendance.view','schedule.view','assignments.view','assignments.submit','reports.view','reports.download','announcements.view','messages.send','materials.view')),
 allowed boolean not null, updated_by bigint references public.users(id), updated_at timestamptz not null default now(),
 check((scope='institution' and role_code is null and user_id is null) or (scope='role' and role_code is not null and user_id is null) or (scope='user' and user_id is not null and role_code is null))
);
create unique index if not exists portal_permission_rule_target on public.portal_permission_rules(institution_id,scope,coalesce(role_code,''),coalesce(user_id,0),permission);
create table if not exists public.grade_visibility_rules (
 id bigint generated by default as identity primary key,
 institution_id bigint not null references public.institutions(id) on delete cascade,
 scope text not null check(scope in ('institution','role','group','student','user')),
 role_code text check(role_code in ('student','parent')),
 group_id bigint references public.groups(id) on delete cascade,
 student_id bigint references public.students(id) on delete cascade,
 user_id bigint references public.users(id) on delete cascade,
 academic_period_id bigint references public.academic_periods(id) on delete cascade,
 allowed boolean not null,updated_by bigint references public.users(id),updated_at timestamptz not null default now(),
 check((scope='institution' and num_nonnulls(role_code,group_id,student_id,user_id)=0)
 or (scope='role' and role_code is not null and num_nonnulls(group_id,student_id,user_id)=0)
 or (scope='group' and group_id is not null and num_nonnulls(role_code,student_id,user_id)=0)
 or (scope='student' and student_id is not null and num_nonnulls(role_code,group_id,user_id)=0)
 or (scope='user' and user_id is not null and num_nonnulls(role_code,group_id,student_id)=0))
);
create unique index if not exists grade_visibility_rule_target on public.grade_visibility_rules(institution_id,scope,coalesce(role_code,''),coalesce(group_id,0),coalesce(student_id,0),coalesce(user_id,0),coalesce(academic_period_id,0));
alter table public.portal_permission_rules enable row level security;
alter table public.grade_visibility_rules enable row level security;
revoke all on public.portal_permission_rules,public.grade_visibility_rules from anon,authenticated;
grant select on public.portal_permission_rules,public.grade_visibility_rules to authenticated;
grant all on public.portal_permission_rules,public.grade_visibility_rules to service_role;
grant usage,select on sequence public.portal_permission_rules_id_seq,public.grade_visibility_rules_id_seq to service_role;

create or replace function public.portal_staff(p_user_id bigint) returns boolean language sql stable security definer set search_path=public as $$
 select exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.user_id=p_user_id and r.code in ('teacher','admin','coordinator','director','super_admin'));
$$;
create or replace function public.portal_permission_for_user(p_user_id bigint,p_permission text) returns boolean language plpgsql stable security definer set search_path=public as $$
declare actor public.users%rowtype; result boolean;
begin
 select * into actor from public.users where id=p_user_id and active and deleted_at is null;
 if actor.id is null then return false; end if;
 if public.portal_staff(actor.id) then return true; end if;
 if p_permission not in ('grades.view','payments.view','attendance.view','schedule.view','assignments.view','assignments.submit','reports.view','reports.download','announcements.view','messages.send','materials.view') then return false; end if;
 select bool_and(allowed) into result from public.portal_permission_rules q where q.institution_id=actor.institution_id and q.permission=p_permission
   and ((q.scope='user' and q.user_id=actor.id) or (q.scope='role' and exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.user_id=actor.id and r.code=q.role_code)) or q.scope='institution')
   and case q.scope when 'user' then 3 when 'role' then 2 else 1 end=(
    select max(case x.scope when 'user' then 3 when 'role' then 2 else 1 end) from public.portal_permission_rules x where x.institution_id=actor.institution_id and x.permission=p_permission
    and ((x.scope='user' and x.user_id=actor.id) or (x.scope='role' and exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.user_id=actor.id and r.code=x.role_code)) or x.scope='institution'));
 return coalesce(result,true);
end $$;
create or replace function public.portal_can(p_permission text) returns boolean language sql stable security definer set search_path=public as $$
 select coalesce((select public.portal_permission_for_user(u.id,p_permission) from public.users u where u.auth_user_id=auth.uid() and u.institution_id=public.current_institution_id() and u.active and u.deleted_at is null),false);
$$;
create or replace function public.portal_student_scope(p_student_id bigint) returns boolean language sql stable security definer set search_path=public as $$
 select exists(select 1 from public.users u join public.students s on s.institution_id=u.institution_id
 where s.id=p_student_id and u.auth_user_id=auth.uid() and u.institution_id=public.current_institution_id() and u.active and u.deleted_at is null and (
   public.portal_staff(u.id) or s.person_id=u.person_id or exists(select 1 from public.parents p join public.parent_students ps on ps.parent_id=p.id where p.person_id=u.person_id and p.institution_id=u.institution_id and ps.student_id=s.id)));
$$;
create or replace function public.portal_class_scope(p_class_id bigint) returns boolean language sql stable security definer set search_path=public as $$
 select exists(select 1 from public.classes c where c.id=p_class_id and c.institution_id=public.current_institution_id() and (
   exists(select 1 from public.users u where u.auth_user_id=auth.uid() and u.active and u.deleted_at is null and public.portal_staff(u.id))
   or exists(select 1 from public.enrollments e where e.group_id=c.group_id and public.portal_student_scope(e.student_id))));
$$;
create or replace function public.portal_can_view_grades(p_student_id bigint,p_period_id bigint default null) returns boolean language plpgsql stable security definer set search_path=public as $$
declare actor public.users%rowtype; result boolean; year_id bigint;
begin
 select * into actor from public.users where auth_user_id=auth.uid() and institution_id=public.current_institution_id() and active and deleted_at is null;
 if actor.id is null or not public.portal_student_scope(p_student_id) then return false; end if;
 if public.portal_staff(actor.id) then return true; end if;
 if not public.portal_can('grades.view') then return false; end if;
 if p_period_id is not null then
   select academic_year_id into year_id from public.academic_periods where id=p_period_id and institution_id=actor.institution_id;
   if not found then return false; end if;
 else
   -- Annual aggregates/PDFs must not disclose a restricted period indirectly.
   if exists(select 1 from public.academic_periods p where p.institution_id=actor.institution_id and not public.portal_can_view_grades(p_student_id,p.id)) then return false; end if;
 end if;
 select q.allowed into result from public.grade_visibility_rules q where q.institution_id=actor.institution_id and (q.academic_period_id is null or q.academic_period_id=p_period_id)
 and (q.scope='institution' or (q.scope='user' and q.user_id=actor.id) or (q.scope='student' and q.student_id=p_student_id)
   or (q.scope='role' and exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.user_id=actor.id and r.code=q.role_code))
   or (q.scope='group' and exists(select 1 from public.enrollments e where e.student_id=p_student_id and e.group_id=q.group_id and (year_id is null or e.academic_year_id=year_id))))
 order by case q.scope when 'user' then 5 when 'student' then 4 when 'group' then 3 when 'role' then 2 else 1 end desc,
   (q.academic_period_id is not null) desc,q.allowed asc limit 1;
 return coalesce(result,true);
end $$;

create or replace function public.portal_access_me() returns jsonb language plpgsql stable security definer set search_path=public as $$
declare actor public.users%rowtype; perms jsonb:='{}'; children jsonb; code text;
begin
 select * into actor from public.users where auth_user_id=auth.uid() and institution_id=public.current_institution_id() and active and deleted_at is null;
 if actor.id is null then raise exception 'Sesión requerida.' using errcode='42501'; end if;
 foreach code in array array['grades.view','payments.view','attendance.view','schedule.view','assignments.view','assignments.submit','reports.view','reports.download','announcements.view','messages.send','materials.view'] loop
   perms:=perms||jsonb_build_object(code,public.portal_can(code));
 end loop;
 select coalesce(jsonb_agg(jsonb_build_object('studentId',s.id,'name',p.first_name||' '||p.last_name,
   'annualVisible',public.portal_can_view_grades(s.id,null),'periods',(select coalesce(jsonb_agg(jsonb_build_object('id',ap.id,'name',ap.name,'visible',public.portal_can_view_grades(s.id,ap.id)) order by ap.start_date),'[]') from public.academic_periods ap where ap.institution_id=actor.institution_id)) order by s.id),'[]') into children
 from public.students s join public.persons p on p.id=s.person_id where s.institution_id=actor.institution_id and not public.portal_staff(actor.id) and public.portal_student_scope(s.id);
 return jsonb_build_object('permissions',perms,'students',children,'staff',public.portal_staff(actor.id));
end $$;

create or replace function public.portal_access_admin() returns jsonb language plpgsql stable security definer set search_path=public as $$
declare inst bigint:=public.current_institution_id();
begin
 if not public.class_admin_actor() or not public.admin_can('roles.edit') then raise exception 'No tienes permiso para gestionar accesos.' using errcode='42501'; end if;
 return jsonb_build_object(
 'permissionRules',(select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') from public.portal_permission_rules q where institution_id=inst),
 'visibilityRules',(select coalesce(jsonb_agg(to_jsonb(q) order by q.id),'[]') from public.grade_visibility_rules q where institution_id=inst),
 'users',(select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'name',u.full_name,'roles',(select jsonb_agg(r.code) from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.user_id=u.id)) order by u.full_name),'[]') from public.users u where u.institution_id=inst and u.active and u.deleted_at is null and not public.portal_staff(u.id)),
 'groups',(select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'name',g.name) order by g.name),'[]') from public.groups g where g.institution_id=inst),
 'students',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',p.first_name||' '||p.last_name) order by p.first_name),'[]') from public.students s join public.persons p on p.id=s.person_id where s.institution_id=inst and s.active),
 'periods',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.start_date),'[]') from public.academic_periods p where p.institution_id=inst));
end $$;

create or replace function public.manage_portal_access(p_action text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare inst bigint:=public.current_institution_id(); actor bigint; target bigint; sc text; rc text; uid bigint; gid bigint; sid bigint; pid bigint; code text; flag boolean;
begin
 if not public.class_admin_actor() or not public.admin_can('roles.edit') then raise exception 'No tienes permiso para gestionar accesos.' using errcode='42501'; end if;
 select id into actor from public.users where auth_user_id=auth.uid();
 if p_action in ('delete_permission','delete_visibility') then
   target:=(p_payload->>'id')::bigint;
   if p_action='delete_permission' then delete from public.portal_permission_rules where id=target and institution_id=inst;
   else delete from public.grade_visibility_rules where id=target and institution_id=inst; end if;
   if not found then raise exception 'Regla no encontrada.' using errcode='22023'; end if;
 elsif p_action in ('save_permission','save_visibility') then
   sc:=p_payload->>'scope'; rc:=nullif(p_payload->>'role',''); uid:=(p_payload->>'userId')::bigint;
   gid:=(p_payload->>'groupId')::bigint; sid:=(p_payload->>'studentId')::bigint; pid:=(p_payload->>'periodId')::bigint;
   if jsonb_typeof(p_payload->'allowed') is distinct from 'boolean' then raise exception 'Indica si el acceso está habilitado.' using errcode='22023'; end if;
   flag:=(p_payload->>'allowed')::boolean;
   if uid is not null and not exists(select 1 from public.users where id=uid and institution_id=inst and active and deleted_at is null and not public.portal_staff(id)) then raise exception 'Usuario fuera de tu institución o perfil de personal.' using errcode='42501'; end if;
   if gid is not null and not exists(select 1 from public.groups where id=gid and institution_id=inst) then raise exception 'Grupo fuera de tu institución.' using errcode='42501'; end if;
   if sid is not null and not exists(select 1 from public.students where id=sid and institution_id=inst) then raise exception 'Estudiante fuera de tu institución.' using errcode='42501'; end if;
   if pid is not null and not exists(select 1 from public.academic_periods where id=pid and institution_id=inst) then raise exception 'Periodo fuera de tu institución.' using errcode='42501'; end if;
   if p_action='save_permission' then
     code:=p_payload->>'permission';
     insert into public.portal_permission_rules(institution_id,scope,role_code,user_id,permission,allowed,updated_by)
       values(inst,sc,rc,uid,code,flag,actor) on conflict (institution_id,scope,(coalesce(role_code,'')),(coalesce(user_id,0)),permission)
       do update set allowed=excluded.allowed,updated_by=actor,updated_at=now();
   else
     insert into public.grade_visibility_rules(institution_id,scope,role_code,group_id,student_id,user_id,academic_period_id,allowed,updated_by)
       values(inst,sc,rc,gid,sid,uid,pid,flag,actor) on conflict (institution_id,scope,(coalesce(role_code,'')),(coalesce(group_id,0)),(coalesce(student_id,0)),(coalesce(user_id,0)),(coalesce(academic_period_id,0)))
       do update set allowed=excluded.allowed,updated_by=actor,updated_at=now();
   end if;
 else raise exception 'Acción inválida.' using errcode='22023'; end if;
 return public.portal_access_admin();
end $$;

drop policy if exists portal_admin_read on public.portal_permission_rules;
create policy portal_admin_read on public.portal_permission_rules for select to authenticated using(institution_id=public.current_institution_id() and public.class_admin_actor() and public.admin_can('roles.edit'));
drop policy if exists portal_admin_read on public.grade_visibility_rules;
create policy portal_admin_read on public.grade_visibility_rules for select to authenticated using(institution_id=public.current_institution_id() and public.class_admin_actor() and public.admin_can('roles.edit'));
drop trigger if exists portal_rules_audit on public.portal_permission_rules;
create trigger portal_rules_audit after insert or update or delete on public.portal_permission_rules for each row execute function public.audit_class_action();
drop trigger if exists grade_visibility_audit on public.grade_visibility_rules;
create trigger grade_visibility_audit after insert or update or delete on public.grade_visibility_rules for each row execute function public.audit_class_action();

-- All grade-bearing tables, including precomputed aggregates and PDFs.
drop policy if exists portal_grade_read on public.grades;
create policy portal_grade_read on public.grades as restrictive for select to authenticated using(public.portal_can_view_grades(student_id,(select academic_period_id from public.evaluations where id=evaluation_id)));
drop policy if exists portal_grade_read on public.period_grades;
create policy portal_grade_read on public.period_grades as restrictive for select to authenticated using(public.portal_can_view_grades(student_id,academic_period_id));
drop policy if exists portal_grade_read on public.report_cards;
create policy portal_grade_read on public.report_cards as restrictive for select to authenticated using(public.portal_can('reports.view') and public.portal_can('reports.download') and public.portal_can_view_grades(student_id,academic_period_id));
drop policy if exists portal_grade_read on public.report_card_lines;
create policy portal_grade_read on public.report_card_lines as restrictive for select to authenticated using(exists(select 1 from public.report_cards r where r.id=report_card_id));
alter view public.student_weighted_averages set (security_invoker=true);

-- Direct Supabase reads obey the same module permissions and family scope.
do $$ declare tbl text; expr text; begin
 for tbl,expr in values
  ('assignments','public.portal_can(''assignments.view'') and public.portal_class_scope(class_id)'),
  ('submissions','public.portal_can(''assignments.view'') and public.portal_student_scope(student_id)'),
  ('schedules','public.portal_can(''schedule.view'') and (class_id is null or public.portal_class_scope(class_id))'),
  ('class_sessions','public.portal_can(''attendance.view'') and public.portal_class_scope(class_id)'),
  ('attendances','public.portal_can(''attendance.view'') and public.portal_student_scope(student_id)'),
  ('charges','public.portal_can(''payments.view'') and public.portal_student_scope(student_id)'),
  ('payments','public.portal_can(''payments.view'') and public.portal_student_scope(student_id)'),
  ('announcements','public.portal_can(''announcements.view'')')
  ,('calendar_events','public.portal_can(''announcements.view'')')
 loop
  execute format('drop policy if exists portal_module_read on public.%I',tbl);
  execute format('create policy portal_module_read on public.%I as restrictive for select to authenticated using(%s)',tbl,expr);
 end loop;
end $$;
-- Students/parents cannot change family links or enrollment groups to bypass
-- a restriction scoped to a child or classroom.
do $$ declare tbl text; cmd text; begin
 foreach tbl in array array['students','parents','parent_students','enrollments'] loop
  foreach cmd in array array['insert','update','delete'] loop
   execute format('drop policy if exists portal_identity_%s on public.%I',cmd,tbl);
   if cmd='insert' then execute format('create policy portal_identity_insert on public.%I as restrictive for insert to authenticated with check(public.class_admin_actor())',tbl);
   elsif cmd='update' then execute format('create policy portal_identity_update on public.%I as restrictive for update to authenticated using(public.class_admin_actor()) with check(public.class_admin_actor())',tbl);
   else execute format('create policy portal_identity_delete on public.%I as restrictive for delete to authenticated using(public.class_admin_actor())',tbl); end if;
  end loop;
 end loop;
end $$;
-- A parent may read a child's submission, but only its student may submit it.
create or replace function public.portal_submit_scope(p_student_id bigint) returns boolean language sql stable security definer set search_path=public as $$
 select public.portal_can('assignments.view') and public.portal_can('assignments.submit') and exists(
 select 1 from public.users u join public.students s on s.institution_id=u.institution_id where s.id=p_student_id
 and u.auth_user_id=auth.uid() and u.institution_id=public.current_institution_id() and u.active and u.deleted_at is null
 and (public.portal_staff(u.id) or (s.person_id=u.person_id and exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.user_id=u.id and r.code='student'))));
$$;
drop policy if exists portal_submission_write on public.submissions;
drop policy if exists portal_submission_files_write on public.submission_files;
do $$ declare tbl text; cmd text; expr text; begin
 foreach tbl in array array['submissions','submission_files'] loop
  expr:=case when tbl='submissions' then 'public.portal_submit_scope(student_id)' else 'exists(select 1 from public.submissions s where s.id=submission_id and public.portal_submit_scope(s.student_id))' end;
  foreach cmd in array array['insert','update','delete'] loop
   execute format('drop policy if exists portal_submission_%s on public.%I',cmd,tbl);
   if cmd='insert' then execute format('create policy portal_submission_insert on public.%I as restrictive for insert to authenticated with check(%s)',tbl,expr);
   elsif cmd='update' then execute format('create policy portal_submission_update on public.%I as restrictive for update to authenticated using(%s) with check(%s)',tbl,expr,expr);
   else execute format('create policy portal_submission_delete on public.%I as restrictive for delete to authenticated using(%s)',tbl,expr); end if;
  end loop;
 end loop;
end $$;

drop policy if exists portal_message_write on public.messages;
create policy portal_message_write on public.messages as restrictive for insert to authenticated with check(public.portal_can('messages.send'));
-- Disabling send also prevents edits/new conversation titles from becoming
-- a second way to send content. Message read receipts remain writable.
drop policy if exists portal_message_edit on public.messages;
create policy portal_message_edit on public.messages as restrictive for update to authenticated using(public.portal_can('messages.send')) with check(public.portal_can('messages.send'));
drop policy if exists portal_conversation_create on public.conversations;
create policy portal_conversation_create on public.conversations as restrictive for insert to authenticated with check(public.portal_can('messages.send'));
drop policy if exists portal_conversation_edit on public.conversations;
create policy portal_conversation_edit on public.conversations as restrictive for update to authenticated using(public.portal_can('messages.send')) with check(public.portal_can('messages.send'));
drop policy if exists portal_participant_add on public.conversation_participants;
create policy portal_participant_add on public.conversation_participants as restrictive for insert to authenticated with check(public.portal_can('messages.send'));

drop policy if exists portal_payment_write on public.payments;
create policy portal_payment_write on public.payments as restrictive for all to authenticated using(public.portal_can('payments.view') and public.portal_student_scope(student_id)) with check(public.portal_can('payments.view') and public.portal_student_scope(student_id));
drop policy if exists portal_announcement_notification on public.notifications;
create policy portal_announcement_notification on public.notifications as restrictive for select to authenticated using(
  (data->>'module' is distinct from 'announcements' and notification_type_id is distinct from (select id from public.catalog_notification_types where code='ANN')) or public.portal_can('announcements.view'));

-- No ordinary user may manufacture grades/aggregates or re-link a grade to an
-- unrestricted period; these records remain writable only by academic staff.
do $$ declare tbl text; cmd text; begin
 foreach tbl in array array['grades','period_grades','evaluations','report_cards','report_card_lines'] loop
  foreach cmd in array array['insert','update','delete'] loop
   execute format('drop policy if exists portal_academic_%s on public.%I',cmd,tbl);
   if cmd='insert' then execute format('create policy portal_academic_insert on public.%I as restrictive for insert to authenticated with check(exists(select 1 from public.users u where u.auth_user_id=auth.uid() and u.institution_id=public.current_institution_id() and u.active and u.deleted_at is null and public.portal_staff(u.id)))',tbl);
   elsif cmd='update' then execute format('create policy portal_academic_update on public.%I as restrictive for update to authenticated using(exists(select 1 from public.users u where u.auth_user_id=auth.uid() and u.institution_id=public.current_institution_id() and u.active and u.deleted_at is null and public.portal_staff(u.id))) with check(exists(select 1 from public.users u where u.auth_user_id=auth.uid() and u.institution_id=public.current_institution_id() and u.active and u.deleted_at is null and public.portal_staff(u.id)))',tbl);
   else execute format('create policy portal_academic_delete on public.%I as restrictive for delete to authenticated using(exists(select 1 from public.users u where u.auth_user_id=auth.uid() and u.institution_id=public.current_institution_id() and u.active and u.deleted_at is null and public.portal_staff(u.id)))',tbl); end if;
  end loop;
 end loop;
end $$;

-- File and Storage guards are evaluated when requesting a new URL/download.
create or replace function public.portal_file_read(p_file_id bigint) returns boolean language plpgsql stable security definer set search_path=public as $$
declare f public.files%rowtype; actor public.users%rowtype;
begin
 select * into actor from public.users where auth_user_id=auth.uid() and institution_id=public.current_institution_id() and active and deleted_at is null;
 select * into f from public.files where id=p_file_id and institution_id=actor.institution_id;
 if actor.id is null or f.id is null then return false; end if;
 if public.portal_staff(actor.id) then return true; end if;
 if exists(select 1 from public.report_cards r where r.institution_id=actor.institution_id and r.pdf_url=f.url) then
   return public.portal_can('reports.view') and public.portal_can('reports.download') and exists(select 1 from public.report_cards r where r.pdf_url=f.url and public.portal_can_view_grades(r.student_id,r.academic_period_id));
 end if;
 if f.uploaded_by=actor.id then return true; end if;
 if exists(select 1 from public.assignment_files af where af.file_id=f.id) then
   return public.portal_can('materials.view') and public.portal_can('assignments.view') and exists(select 1 from public.assignment_files af join public.assignments a on a.id=af.assignment_id where af.file_id=f.id and public.portal_class_scope(a.class_id));
 end if;
 if exists(select 1 from public.submission_files sf where sf.file_id=f.id) then
   return public.portal_can('materials.view') and public.portal_can('assignments.view') and exists(select 1 from public.submission_files sf join public.submissions s on s.id=sf.submission_id where sf.file_id=f.id and public.portal_student_scope(s.student_id));
 end if;
 return public.portal_can('materials.view');
end $$;
drop policy if exists portal_file_read on public.files;
create policy portal_file_read on public.files as restrictive for select to authenticated using(public.portal_file_read(id));
drop policy if exists portal_assignment_files_read on public.assignment_files;
create policy portal_assignment_files_read on public.assignment_files as restrictive for select to authenticated using(public.portal_can('materials.view') and exists(select 1 from public.assignments a where a.id=assignment_id));
drop policy if exists portal_submission_files_read on public.submission_files;
create policy portal_submission_files_read on public.submission_files as restrictive for select to authenticated using(exists(select 1 from public.submissions s where s.id=submission_id));
drop policy if exists portal_storage_read on storage.objects;
create policy portal_storage_read on storage.objects as restrictive for select to authenticated using(bucket_id<>'files' or exists(select 1 from public.files f where f.storage_path=name and public.portal_file_read(f.id)));
create or replace function public.guard_portal_file_owner() returns trigger language plpgsql security definer set search_path=public as $$
declare actor bigint;
begin
 select id into actor from public.users where auth_user_id=auth.uid() and active and deleted_at is null;
 if auth.uid() is null or public.portal_staff(actor) then return new; end if;
 if tg_op='UPDATE' and (old.uploaded_by<>actor or new.storage_path is distinct from old.storage_path or new.uploaded_by is distinct from old.uploaded_by) then
   raise exception 'No puedes modificar la propiedad de este archivo.' using errcode='42501'; end if;
 if new.uploaded_by is distinct from actor or not exists(select 1 from storage.objects o where o.bucket_id='files' and o.name=new.storage_path and o.owner_id=auth.uid()::text) then
   raise exception 'El archivo no pertenece a tu cuenta.' using errcode='42501'; end if;
 return new;
end $$;
drop trigger if exists portal_file_owner_guard on public.files;
create trigger portal_file_owner_guard before insert or update on public.files for each row execute function public.guard_portal_file_owner();

