grant execute on function public.portal_can(text),public.portal_student_scope(bigint),public.portal_class_scope(bigint),public.portal_can_view_grades(bigint,bigint),public.portal_access_me(),public.portal_access_admin(),public.manage_portal_access(text,jsonb),public.portal_file_read(bigint),public.portal_submit_scope(bigint),public.portal_staff(bigint) to authenticated;
